"""
OlaMate collector — connects to the scooter's gRPC service,
streams CAN frames, decodes them, and stores telemetry in SQLite.

Usage:
    SCOOTER_IP=192.168.1.x python -m collector.main
"""

import os
import sys
import time
import json
import logging
import grpc

from . import can_decoder
from .database import init_db, get_db, insert_telemetry, insert_snapshot, start_session, end_session

# These are generated by grpc_tools.protoc from wifican.proto
# Run: python -m grpc_tools.protoc -I proto --python_out=collector --grpc_python_out=collector proto/wifican.proto
try:
    from . import wifican_pb2
    from . import wifican_pb2_grpc
except ImportError:
    print("gRPC stubs not found. Generate them with:")
    print("  python -m grpc_tools.protoc -I proto --python_out=collector --grpc_python_out=collector proto/wifican.proto")
    sys.exit(1)

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("olamate")

SCOOTER_IP = os.environ.get("SCOOTER_IP")
GRPC_PORT = os.environ.get("GRPC_PORT", "50005")
DB_PATH = os.environ.get("DB_PATH", "./olamate.db")
TELEMETRY_INTERVAL = 1.0  # seconds between DB writes
TELEMETRY_INTERVAL_LOW_SOC = 0.5  # faster logging below SOC threshold
LOW_SOC_THRESHOLD = 30.0  # % — switch to fast logging below this
CELL_VOLTAGE_WARN = 3.2  # V — log warning when any cell drops below
CELL_VOLTAGE_CRITICAL = 3.0  # V — log critical when any cell drops below
SNAPSHOT_INTERVAL = 300.0  # seconds between health snapshots
MIN_RIDE_SPEED = 3.0  # km/h — below this, treat speed as sensor noise
MIN_RIDE_DURATION = 30.0  # seconds — discard rides shorter than this


class Collector:
    def __init__(self, scooter_addr: str, db_path: str):
        self.scooter_addr = scooter_addr
        self.db_path = db_path
        self.latest_frames: dict[int, can_decoder.DecodedFrame] = {}
        self.ride_session_id = None
        self.charge_session_id = None
        self.last_speed = 0.0
        self.last_soc = 100.0
        self.last_db_write = 0.0
        self.last_snapshot = 0.0
        self.warned_cells: set[int] = set()
        self.charger_plugged = False
        self.ride_start_time = 0.0

    def connect(self):
        """Create gRPC channel and stub."""
        log.info(f"Connecting to {self.scooter_addr}...")
        self.channel = grpc.insecure_channel(
            self.scooter_addr,
            options=[
                ("grpc.keepalive_time_ms", 10000),
                ("grpc.keepalive_timeout_ms", 5000),
                ("grpc.keepalive_permit_without_calls", 1),
                ("grpc.http2.max_pings_without_data", 0),
            ],
        )
        self.stub = wifican_pb2_grpc.WifiCanRpcStub(self.channel)
        log.info("Connected.")

    def stream_can(self):
        """Stream CAN frames and process them."""
        log.info("Starting CAN stream...")
        from google.protobuf.empty_pb2 import Empty
        empty = Empty()

        try:
            stream = self.stub.CanDumpStream(empty)
            last_frame_time = time.time()
            while True:
                try:
                    packet = next(stream)
                except StopIteration:
                    log.warning("CAN stream ended (server closed)")
                    break

                now = time.time()
                last_frame_time = now
                frame = can_decoder.decode_grpc_frame(packet.can_frame, now)
                if frame:
                    self.latest_frames[frame.can_id] = frame
                    self.on_frame(frame, now)

        except grpc.RpcError as e:
            log.error(f"gRPC stream error: {e.code()} {e.details()}")
            raise

    @property
    def current_session_id(self):
        return self.ride_session_id or self.charge_session_id

    def on_frame(self, frame: can_decoder.DecodedFrame, now: float):
        """Handle a decoded frame — detect sessions, write telemetry."""
        # Detect ride start/stop based on speed (with noise filtering)
        if frame.can_id == 0x313:
            speed = frame.signals.get("speed_kmph", 0)
            if speed >= MIN_RIDE_SPEED and self.last_speed < MIN_RIDE_SPEED and self.ride_session_id is None:
                self.start_ride(now)
            elif speed < MIN_RIDE_SPEED and self.last_speed >= MIN_RIDE_SPEED and self.ride_session_id is not None:
                self.end_ride(now)
            self.last_speed = speed

        # Detect charge start/stop based on charger plug state
        if frame.can_id == 0x62D:
            plugged = frame.signals.get("charger_plugged_in", 0) == 1
            if plugged and not self.charger_plugged and self.charge_session_id is None:
                self.start_charge(now)
            elif not plugged and self.charger_plugged and self.charge_session_id is not None:
                self.end_charge(now)
            self.charger_plugged = plugged

        # Track SOC changes and cell warnings
        if frame.can_id == 0x120:
            soc = frame.signals.get("soc_percent", self.last_soc)
            if soc is not None:
                drop = self.last_soc - soc
                if drop > 5:
                    log.warning(f"SOC dropped {drop:.1f}% in one step ({self.last_soc:.1f}% → {soc:.1f}%)")
                if soc < LOW_SOC_THRESHOLD and self.last_soc >= LOW_SOC_THRESHOLD:
                    log.warning(f"SOC below {LOW_SOC_THRESHOLD}% — switching to fast logging")
                self.last_soc = soc

        if frame.can_id in (0x1A5, 0x1A6, 0x1A9, 0x1AA):
            for name, voltage in frame.signals.items():
                if not name.endswith("_V") or voltage <= 0:
                    continue
                cell = name.split("_")[1]
                if voltage < CELL_VOLTAGE_CRITICAL:
                    log.critical(f"Cell {cell} at {voltage:.3f}V — below critical threshold!")
                elif voltage < CELL_VOLTAGE_WARN and int(cell) not in self.warned_cells:
                    log.warning(f"Cell {cell} at {voltage:.3f}V — approaching low voltage")
                    self.warned_cells.add(int(cell))

        # Periodic telemetry write — faster when SOC is low
        interval = TELEMETRY_INTERVAL_LOW_SOC if self.last_soc < LOW_SOC_THRESHOLD else TELEMETRY_INTERVAL
        if now - self.last_db_write >= interval:
            self.write_telemetry(now)
            self.last_db_write = now

        # Periodic health snapshot
        if now - self.last_snapshot >= SNAPSHOT_INTERVAL:
            self.write_snapshot(now)
            self.last_snapshot = now

    def start_ride(self, now: float):
        """Start a new ride session."""
        if self.charge_session_id is not None:
            self.end_charge(now)
        soc = self._get_signal(0x120, "soc_percent")
        odo = self._get_signal(0x356, "odometer_m")
        with get_db(self.db_path) as conn:
            self.ride_session_id = start_session(
                conn, "ride", now,
                start_soc=soc,
                start_odometer=int(odo) if odo else None,
            )
        self.ride_start_time = now
        log.info(f"Ride started (session {self.ride_session_id}, SOC={soc}%)")

    def end_ride(self, now: float):
        """End the current ride session. Discard if too short."""
        if not self.ride_session_id:
            return

        duration = now - self.ride_start_time
        soc = self._get_signal(0x120, "soc_percent")
        odo = self._get_signal(0x356, "odometer_m")

        with get_db(self.db_path) as conn:
            if duration < MIN_RIDE_DURATION:
                conn.execute("DELETE FROM telemetry WHERE session_id = ?", (self.ride_session_id,))
                conn.execute("DELETE FROM sessions WHERE id = ?", (self.ride_session_id,))
                log.info(f"Discarded jitter ride (session {self.ride_session_id}, {duration:.0f}s)")
            else:
                end_session(conn, self.ride_session_id,
                            end_time=now, end_soc=soc,
                            end_odometer=int(odo) if odo else None)
                log.info(f"Ride ended (session {self.ride_session_id}, SOC={soc}%, {duration:.0f}s)")
        self.ride_session_id = None
        self.ride_start_time = 0.0

    def start_charge(self, now: float):
        """Start a new charge session."""
        if self.ride_session_id is not None:
            self.end_ride(now)
        soc = self._get_signal(0x120, "soc_percent")
        with get_db(self.db_path) as conn:
            self.charge_session_id = start_session(
                conn, "charge", now, start_soc=soc,
            )
        log.info(f"Charge started (session {self.charge_session_id}, SOC={soc}%)")

    def end_charge(self, now: float):
        """End the current charge session."""
        if not self.charge_session_id:
            return
        soc = self._get_signal(0x120, "soc_percent")
        with get_db(self.db_path) as conn:
            end_session(conn, self.charge_session_id,
                        end_time=now, end_soc=soc)
        log.info(f"Charge ended (session {self.charge_session_id}, SOC={soc}%)")
        self.charge_session_id = None

    def write_telemetry(self, now: float):
        """Write current state to the telemetry table."""
        f = self.latest_frames
        row = {"timestamp": now, "session_id": self.current_session_id}

        # Battery
        row["soc"] = self._get_signal(0x120, "soc_percent")
        row["current"] = self._get_signal(0x120, "battery_current_A")
        row["voltage"] = self._get_signal(0x150, "bus_voltage_V")
        row["soh"] = self._get_signal(0x150, "pack_soh_percent")
        row["regen_power_limit"] = self._get_signal(0x140, "regen_power_limit_W")
        row["discharge_power_limit"] = self._get_signal(0x140, "discharge_power_limit_W")

        # Cell voltages
        cells = can_decoder.get_cell_voltages(f)
        for cell_num, voltage in cells:
            row[f"cell_{cell_num}"] = voltage
        voltages = [v for _, v in cells if v > 0]
        if voltages:
            row["cell_min"] = min(voltages)
            row["cell_max"] = max(voltages)
            row["cell_spread_mV"] = round((max(voltages) - min(voltages)) * 1000, 1)

        # Temperatures
        row["temp_effective"] = self._get_signal(0x160, "effective_temp_C")
        row["temp_min"] = self._get_signal(0x160, "temp_min_C")
        row["temp_max"] = self._get_signal(0x160, "temp_max_C")
        for i in range(1, 7):
            can_id = 0x1A4 if i <= 4 else 0x1A7
            row[f"temp_pack_{i}"] = self._get_signal(can_id, f"pack_temp_{i}_C")
        row["temp_mcu"] = self._get_signal(0x313, "mcu_temp_C")
        row["temp_motor"] = self._get_signal(0x313, "motor_temp_C")

        # Motor/driving
        row["speed"] = self._get_signal(0x313, "speed_kmph")
        row["motor_rpm"] = self._get_signal(0x313, "motor_rpm")
        row["odometer"] = self._get_signal(0x356, "odometer_m")

        # Range
        row["range_normal"] = self._get_signal(0x6F4, "range_normal_km")
        row["range_sport"] = self._get_signal(0x6F4, "range_sport_km")
        row["range_hyper"] = self._get_signal(0x6F4, "range_hyper_km")

        # Status
        row["side_stand"] = self._get_signal(0x353, "side_stand")
        row["regen_availability"] = self._get_signal(0x683, "regen_availability")
        row["hill_hold"] = self._get_signal(0x683, "hill_hold")
        row["drive_mode"] = self._get_signal(0x113, "vehicle_discharge_mode")

        with get_db(self.db_path) as conn:
            insert_telemetry(conn, row)

    def write_snapshot(self, now: float):
        """Write a health snapshot (less frequent, for long-term tracking)."""
        cells = can_decoder.get_cell_voltages(self.latest_frames)
        voltages = [v for _, v in cells if v > 0]

        snapshot = {
            "timestamp": now,
            "soc": self._get_signal(0x120, "soc_percent"),
            "soh": self._get_signal(0x150, "pack_soh_percent"),
            "voltage": self._get_signal(0x150, "bus_voltage_V"),
            "odometer": self._get_signal(0x356, "odometer_m"),
            "temp_effective": self._get_signal(0x160, "effective_temp_C"),
            "cells_json": json.dumps(voltages) if voltages else None,
        }

        if voltages:
            snapshot["cell_spread_mV"] = round((max(voltages) - min(voltages)) * 1000, 1)

        with get_db(self.db_path) as conn:
            insert_snapshot(conn, snapshot)
        log.info(f"Health snapshot saved (SOC={snapshot['soc']}%, spread={snapshot.get('cell_spread_mV')}mV)")

    def _get_signal(self, can_id: int, signal_name: str):
        """Get a signal value from the latest frames, or None."""
        frame = self.latest_frames.get(can_id)
        if frame:
            return frame.signals.get(signal_name)
        return None

    def run(self):
        """Main loop with reconnection."""
        init_db(self.db_path)
        log.info(f"Database initialized at {self.db_path}")

        while True:
            try:
                self.connect()
                self.stream_can()
            except (grpc.RpcError, Exception) as e:
                log.warning(f"Connection lost: {e}. Reconnecting in 10s...")
                time.sleep(10)


def main():
    if not SCOOTER_IP:
        print("Error: SCOOTER_IP environment variable is required.")
        print("Usage: SCOOTER_IP=192.168.1.x python -m collector.main")
        sys.exit(1)

    addr = f"{SCOOTER_IP}:{GRPC_PORT}"
    collector = Collector(addr, DB_PATH)
    collector.run()


if __name__ == "__main__":
    main()
